// === Tab: mySketch ===
//Made for the #wccChallenge on the theme of 'reflections'
//The text is taken from writing prompts to get students to reflect on their learning.
//So, the idea was to play on the idea of reflectional symmetry and reflection as in to ponder or think about
//Using text also brought in the reflectional symmetry in many letters 
//the basic code came together rather quickly for once, with a couple hours of tweaking after.

let reflected
let reflections=[]
let xer=0
let easing=0.0075
let words=['What seemed to be the most important ideas?', 'My role in the learning process today was...',' I noticed...', 'I was at my best today when...','What did you assume...','What do you think you might understand about _____', 'What is the most likely source of confusion...', 'What is the difference between misunderstanding and not yet knowing?','What do you already know about _____', 'How did your understanding of _______ change today?','One thing I would like to improve upon is ...', 'I know...', 'I would like to know...', 'One thing I am still curious about is...']


function preload() {
	font= loadFont('https://openprocessing.org/sketch/1605919/files/Bitter-Regular.ttf')
}

function setup() {
  createCanvas(windowWidth, windowHeight);

  reflected= createGraphics(width/2, height/2)
	reflected.textFont(font)

	let worder=floor(random(0, words.length))
	reflections.push(new reflection(worder, 0))
	reflections.push(new reflection(worder, 1))
}

function draw() {
  xer+=0.1
  background(255)
	reflected.clear()
  if(frameCount%130==0){
		var worder=floor(random(0, words.length))
	reflections.push(new reflection(worder, 0))
	reflections.push(new reflection(worder, 1))
  }
  for(let i=reflections.length-1; i>=0; i--){
    reflections[i].update();
    reflections[i].show();
  }

  image(reflected, 0, 0)
  push()
  translate(0, height)
  scale(1, -1)
  image(reflected, 0, 0)
  pop()
  push()
  translate(width, 0)
  scale(-1, 1)
  image(reflected, 0, 0)
  pop()
  push()
  translate(width, height)
  scale(-1, -1)
  image(reflected, 0, 0)
  pop()
}


class reflection{
  constructor(word, dir){
    let wordPicker= word
    this.words=words[wordPicker]
		this.dir=dir
		this.size=random(reflected.height/25, reflected.height/4)
		switch(this.dir){
			case 0:
			this.x=-this.size*this.words.length-10
			this.y= randomGaussian(reflected.height*0.75 +this.size, reflected.height*0.25)
				break;
			case 1:
					this.x= randomGaussian(reflected.width*0.75 +this.size, reflected.width*0.25)
				this.y= -this.size 
				break;
		}

  }

  update(){

		 if(this.dir==0)	{	let dx = reflected.width - this.x;
    this.x += dx * easing;

    if(this.x>reflected.width*1.9){
       let index = reflections.indexOf(this);
     reflections.splice(index, 1);	
    }
											}
	if(this.dir==1){	
				let dy= (reflected.height+this.size)-this.y;
				this.y += dy *easing;

				if(this.y>(reflected.height+this.size)*1.9){
					var index = reflections.indexOf(this);
     reflections.splice(index, 1);
				}
	}	

  }

  show(){
  reflected.textSize(this.size)
  reflected.fill(0)
  reflected.noStroke()
  reflected.text(this.words, this.x, this.y)
  }
}

